package app.daemon.deck;
import android.app.*;import android.content.*;
public class AlarmReceiver extends BroadcastReceiver {public void onReceive(Context c,Intent i){Alarms.channel(c);Intent open=new Intent(c,MainActivity.class).setFlags(Intent.FLAG_ACTIVITY_NEW_TASK|Intent.FLAG_ACTIVITY_CLEAR_TOP);PendingIntent content=PendingIntent.getActivity(c,0,open,PendingIntent.FLAG_UPDATE_CURRENT|PendingIntent.FLAG_IMMUTABLE);Notification n=new Notification.Builder(c,Alarms.CHANNEL).setSmallIcon(android.R.drawable.ic_lock_idle_alarm).setContentTitle(i.getStringExtra("title")).setContentText(i.getStringExtra("body")).setStyle(new Notification.BigTextStyle().bigText(i.getStringExtra("body"))).setCategory(Notification.CATEGORY_ALARM).setContentIntent(content).setAutoCancel(true).build();try{((NotificationManager)c.getSystemService(Context.NOTIFICATION_SERVICE)).notify(i.getDataString().hashCode(),n);}catch(SecurityException ignored){}}}
